import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]/"outputs/qwen21_story_16_sunset"
titles=["Sunset departure","Mirror of memories","A sudden glance","An old letter","Recognizing the handwriting","The lights come on","Through the old alley","Wind before the rain","First drops of rain","Reflection in the window","After the rain","A figure on the bridge","Approaching each other","The reunion","Together by the river","A new morning"]
actions=["She slowly pushes her silver bicycle forward beside the river as her loose hair and black coat move in the evening breeze. The camera tracks beside her smoothly.","The bicycle rolls slowly past a convex street mirror; the camera gently pushes toward the mirror while the sunset reflections drift across its surface.","She turns her head over her shoulder, blinks naturally, and a faint expression of recognition crosses her face. The camera makes a subtle push-in.","Her hand reaches into the bicycle basket, gently lifting the weathered envelope as the small flowers tremble in the breeze.","She unfolds the letter and reads quietly; her eyes soften and her fingers tighten slightly around the paper. Slow cinematic dolly-in.","Streetlights glow on one after another along the river. She rests her hands on the bicycle handlebars and looks toward the distant bridge.","She pedals steadily through the narrow old street, passing warm shop windows as reflections slide across the cobblestones. Smooth side-tracking shot.","A sudden gust lifts her hair and coat; petals swirl around the bicycle as she holds the letter close. The camera remains steady.","Fine rain begins to fall beyond the cafe awning. She gently wheels her bicycle under shelter, looking out at the rain.","Raindrops trickle down the cafe glass while she looks through the window and slowly shifts her gaze. Subtle reflections shimmer on the glass.","She rides her bicycle slowly along the wet street at blue hour, with moving reflections from passing lights. Gentle tracking camera.","She stops at the bridge entrance, one foot on the ground, looking toward the distant man under the streetlamp. Slow forward dolly.","She walks her bicycle slowly toward the waiting man; both keep their eyes on each other. The camera tracks alongside at walking pace.","They exchange small relieved smiles and gently step closer at the bridge railing. The bicycle remains beside them. Subtle camera push-in.","The two sit quietly on the riverside bench, turning slightly toward each other as the city lights shimmer on the water. Slow wide camera drift.","Two bicycles stand by the river railing as the distant couple walks away together toward sunrise. The camera slowly pulls back."]
identity="Maintain the exact appearance, hairstyle, clothing, bicycle and composition of the provided first-frame image. Photorealistic cinematic 35mm film, natural realistic movement, stable anatomy, no morphing, no extra limbs, no text, no abrupt scene cuts. "
sound=" Ambient sound: gentle natural city ambience, distant river breeze, soft bicycle sounds; no dialogue. No background music."
items=[]
for i,(title,action) in enumerate(zip(titles,actions),1):
    img=root/f"{i:02d}"/f"{i:02d}.png"
    if not img.exists():continue
    prompt=(identity + "Timeline: [0-2s] Begin exactly from the reference still; establish the original pose, lighting and environment, then start the following action gently: " + action + " [2-4s] Continue the same physical action with subtle secondary motion in hair, clothing, reflections and background, without changing identity or framing. [4-5s] Let the motion settle naturally into a coherent end pose, maintaining the same camera direction and vertical framing. Camera: one smooth, controlled cinematic shot, no abrupt zooms or cuts. " + sound)
    items.append({"scene":i,"title":title,"first_frame":str(img),"prompt":prompt,"steps":6,"workflow":"Pika H3 Flex FL2VA"})
out=root/"pika_video_jobs.json"
out.write_text(json.dumps(items,ensure_ascii=False,indent=2),encoding="utf-8")
print("prepared",len(items),"jobs:",out)


